/**
 * @return array<int, array{regex: string, method: string, key: string, controller: string}>
 */
private function getIndexCache(): array
{
    $indexCacheItem = $this->getCache()->get(self::CACHE_INDEX_KEY);
    if (!$indexCacheItem instanceof CacheItem) {
        return [];
    }

    $indexCache = json_decode($indexCacheItem->getValue(), true);
    if (!$indexCache) {
        return [];
    }

    return $indexCache;
}

